components.css:
.quote__figure { margin: 0; padding: 2rem 1.5rem; border-radius: 0.5rem; background: var(--cms-color-surface); }
.quote__text { margin: 0 0 1rem; font-size: 1.375rem; line-height: 1.4; color: var(--cms-color-text); }
.quote__text p { margin: 0; }
.quote__caption { display: flex; flex-wrap: wrap; align-items: center; gap: 0.25rem 0.75rem; }
.quote__portrait { width: 3rem; height: 3rem; border-radius: 50%; object-fit: cover; }
.quote__author { font-weight: 700; color: var(--cms-color-text); }
.quote__role { color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .quote__figure { padding: 3rem; } .quote__text { font-size: 1.75rem; } }

.imagetext { display: grid; gap: 1.5rem; align-items: center; }
.imagetext__image { display: block; width: 100%; height: auto; border-radius: 0.5rem; }
.imagetext__title { margin: 0 0 0.75rem; color: var(--cms-color-text); }
.imagetext__text { color: var(--cms-color-text); }
.imagetext__link { display: inline-block; margin-top: 1rem; font-weight: 700; color: var(--cms-color-accent); }
@media (min-width: 48rem) { .imagetext { grid-template-columns: 1fr 1fr; gap: 3rem; } .imagetext--right .imagetext__media { order: 2; } }

.figures__title { margin: 0 0 1.5rem; color: var(--cms-color-text); }
.figures__list { display: grid; gap: 1.5rem; margin: 0; padding: 0; list-style: none; }
.figure { display: flex; flex-direction: column; gap: 0.25rem; }
.figure__value { font-size: 2.5rem; font-weight: 700; line-height: 1; color: var(--cms-color-text); }
.figure__label { font-weight: 700; color: var(--cms-color-text); }
.figure__note { color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .figures__list { grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr)); } }

.steps__list { display: grid; gap: 1.5rem; padding: 0; list-style: none; counter-reset: step; }
.step { counter-increment: step; padding-top: 1rem; border-top: 2px solid var(--cms-color-accent); }
.step__title { margin: 0 0 0.5rem; }
.step__title::before { content: counter(step) ". "; }
.step__text { margin: 0; color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .steps__list { grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr)); } }

.carousel__title { margin: 0 0 1rem; color: var(--cms-color-text); }
.carousel__viewport { position: relative; overflow-x: auto; scroll-snap-type: x mandatory; overscroll-behavior-x: contain; }
.carousel__viewport:focus-visible { outline: 2px solid var(--cms-color-text); outline-offset: 2px; }
.carousel__track { display: flex; gap: 1rem; margin: 0; padding: 0 0 0.5rem; list-style: none; }
.carousel__slide { flex: 0 0 85%; scroll-snap-align: start; }
.carousel__image { display: block; width: 100%; height: auto; border-radius: 0.5rem; }
.carousel__caption { margin: 0.5rem 0 0; color: var(--cms-color-text-muted); }
@media (min-width: 48rem) { .carousel__slide { flex-basis: 40%; } }

.faq__title { margin: 0 0 1rem; color: var(--cms-color-text); }
.faq__item { padding: 0.75rem 0; border-bottom: 1px solid var(--cms-color-border); }
.faq__question { cursor: pointer; font-weight: 700; color: var(--cms-color-text); }
.faq__answer { padding-top: 0.5rem; color: var(--cms-color-text-muted); }
